# MediQuest Triage Desk — eval run on a Kaggle GPU (T4).
# Installs Ollama, pulls the open-weights models, and runs the real agent (LangGraph + both MCP servers) over the
# eval set. Synthetic patients only. Generated by kaggle/push.sh — edit kernel_template.py, not the build output.
import base64, io, os, shutil, subprocess, tarfile, time, urllib.request

# model@temperature@runs, comma-separated
CONFIGS = [c.split("@") for c in "__CONFIGS__".split(",")]
MODELS = sorted({m for m, _, _ in CONFIGS})
APP = "/tmp/app"  # outside /kaggle/working so the venv is not saved as kernel output
OUT = "/kaggle/working/out"
SOURCE_TAR_B64 = "__SOURCE__"


def sh(cmd, **kw):
    print(f"\n$ {cmd}", flush=True)
    subprocess.run(cmd, shell=True, check=True, **kw)


shutil.rmtree(APP, ignore_errors=True)
os.makedirs(OUT, exist_ok=True)
tarfile.open(fileobj=io.BytesIO(base64.b64decode(SOURCE_TAR_B64)), mode="r:gz").extractall(APP)

sh("nvidia-smi -L || true")
sh("apt-get -qq update >/dev/null && apt-get -qq install -y pciutils lshw zstd >/dev/null || true")
sh("curl -fsSL https://ollama.com/install.sh | sh")
server = subprocess.Popen(["ollama", "serve"], stdout=open(f"{OUT}/ollama.log", "w"), stderr=subprocess.STDOUT)
for _ in range(60):
    try:
        urllib.request.urlopen("http://127.0.0.1:11434/api/tags", timeout=2)
        break
    except Exception:
        time.sleep(1)
for m in MODELS:
    sh(f"ollama pull {m}")

sh("pip install -q uv")
env = {**os.environ, "TRIAGE_FACILITY_TZ": "Africa/Nairobi", "UV_PYTHON": "3.12"}
sh("uv sync --frozen", cwd=APP, env=env)
sh("uv run pytest -q", cwd=APP, env=env)
for m, temp, runs in CONFIGS:
    tag = f'{m.replace(":", "-").replace("/", "_")}-t{temp}'
    sh(f"uv run triage-desk eval --runs {runs} --out {OUT}/results-{tag}.json 2>&1 | tee {OUT}/eval-{tag}.log",
       cwd=APP, env={**env, "TRIAGE_MODEL": m, "TRIAGE_TEMPERATURE": temp})
sh(f"mkdir -p {OUT}/audit && for d in {APP}/evals/runs/*; do cp $d/audit.jsonl {OUT}/audit/$(basename $d).jsonl; done")
server.terminate()
print("done", flush=True)
